package shop.ultimatesmp.tempgrants;
import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;import java.lang.reflect.*;import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.block.*;import org.bukkit.event.player.*;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.permissions.PermissionAttachment;import org.bukkit.persistence.PersistentDataType;import org.bukkit.plugin.java.JavaPlugin;
public final class UltimateTempGrants extends JavaPlugin implements Listener,TabCompleter {
 private final ExecutorService io=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"UltimateTempGrants-Store");t.setDaemon(true);return t;});private final AtomicBoolean reading=new AtomicBoolean();private final Map<UUID,List<Grant>> cached=new HashMap<>();private final Map<UUID,Map<String,Long>> appliedRanks=new HashMap<>();private final Map<UUID,PermissionAttachment> permissions=new HashMap<>();private final Map<UUID,Set<String>> appliedPerms=new HashMap<>();private final Set<UUID> pending=new HashSet<>();private JavaPlugin ranks,network;private Method normalize,overlay,networkReady;private NamespacedKey voucherId;private GrantStore store;private volatile boolean stopping;private boolean initialized;
 @Override public void onEnable(){saveDefaultConfig();voucherId=new NamespacedKey(this,"voucher-id");try{
  ranks=(JavaPlugin)Bukkit.getPluginManager().getPlugin("UltimateRanks");normalize=ranks.getClass().getMethod("normalizeTemporaryRank",String.class);overlay=ranks.getClass().getMethod("setTemporaryRankExpiries",UUID.class,Map.class);
  network=(JavaPlugin)Bukkit.getPluginManager().getPlugin("BlinkNetwork");if(network!=null){if(!network.isEnabled())throw new IllegalStateException("BlinkNetwork is disabled");networkReady=network.getClass().getMethod("isPlayerReady",Player.class);}
  String mode=getConfig().getString("storage","auto");if(!Set.of("auto","local").contains(mode))throw new IllegalArgumentException("Invalid storage mode");String url=null,user="",password="";if(mode.equals("auto")&&network!=null){url=credential("BLINK_NETWORK_JDBC_URL","database.jdbc-url").replaceFirst("^jdbc:mysql:","jdbc:mariadb:");user=credential("BLINK_NETWORK_DB_USER","database.username");password=credential("BLINK_NETWORK_DB_PASSWORD","database.password");if(!url.startsWith("jdbc:mariadb:"))throw new IllegalArgumentException("MySQL/MariaDB required");}
  store=new GrantStore(getDataFolder().toPath().resolve("data.yml"),url,user,password);Bukkit.getPluginManager().registerEvents(this,this);Objects.requireNonNull(getCommand("tempgrant")).setTabCompleter(this);Bukkit.getScheduler().runTaskTimer(this,this::refresh,1,20L*Math.max(2,getConfig().getInt("refresh-seconds",5)));Bukkit.getScheduler().runTaskTimer(this,this::pulse,20,20);getLogger().info("Voucher storage: "+(url==null?"local":"shared MySQL/MariaDB")+"; requires UltimateRanks 1.3.2.");
 }catch(Exception e){getLogger().severe("Setup failed ("+e.getClass().getSimpleName()+"). Install UltimateRanks 1.3.2 and check storage configuration.");Bukkit.getPluginManager().disablePlugin(this);}}
 private String credential(String key,String path){String value=System.getenv(key);return value==null||value.isBlank()?network.getConfig().getString(path,""):value;}
 private void main(Runnable r){if(!stopping&&isEnabled())Bukkit.getScheduler().runTask(this,()->{if(!stopping)r.run();});}
 private boolean ready(Player p){if(!initialized)return false;if(network==null)return p.isOnline();try{return network.isEnabled()&&Boolean.TRUE.equals(networkReady.invoke(network,p));}catch(Exception e){return false;}}
 private boolean admin(CommandSender s){return s.hasPermission("ultimatetempgrants.admin")||s instanceof Player p&&p.hasPermission("ultimateranks.rank.owner");}
 private void tell(CommandSender s,String text){s.sendMessage("§6[UltimateTempGrants] §f"+text);}
 private void refresh(){if(stopping||!reading.compareAndSet(false,true))return;List<UUID> players=Bukkit.getOnlinePlayers().stream().map(Player::getUniqueId).toList();io.execute(()->{try{store.initialize();Map<UUID,List<Grant>> values=new HashMap<>();for(UUID id:players)values.put(id,store.active(id,System.currentTimeMillis()));main(()->{initialized=true;for(var e:values.entrySet())if(Bukkit.getPlayer(e.getKey())!=null)cached.put(e.getKey(),e.getValue());pulse();});}catch(Exception e){getLogger().warning("Voucher storage unavailable ("+e.getClass().getSimpleName()+"); cached timers still expire.");}finally{reading.set(false);}});}
 private void pulse(){long now=System.currentTimeMillis();for(Player p:Bukkit.getOnlinePlayers()){List<Grant> values=cached.getOrDefault(p.getUniqueId(),List.of());Map<String,Long> rankValues=new TreeMap<>();Set<String> nodes=new TreeSet<>();for(Grant g:values)if(g.expiry()>now){if(g.kind().equals("rank"))rankValues.put(g.target(),g.expiry());else nodes.add(g.target());}
  UUID id=p.getUniqueId();if(!rankValues.equals(appliedRanks.getOrDefault(id,Map.of()))){try{overlay.invoke(ranks,id,rankValues);appliedRanks.put(id,Map.copyOf(rankValues));}catch(Exception e){getLogger().warning("Temporary rank overlay unavailable; check UltimateRanks version.");}}
  boolean missing=nodes.stream().anyMatch(node->!p.hasPermission(node));if(!nodes.equals(appliedPerms.getOrDefault(id,Set.of()))||missing){PermissionAttachment old=permissions.remove(id);if(old!=null)p.removeAttachment(old);if(!nodes.isEmpty()){PermissionAttachment a=p.addAttachment(this);for(String node:nodes)a.setPermission(node,true);permissions.put(id,a);}appliedPerms.put(id,Set.copyOf(nodes));p.updateCommands();}
 }}
 private ItemStack item(GrantStore.Voucher voucher){ItemStack item=new ItemStack(Material.PAPER);ItemMeta meta=item.getItemMeta();meta.setDisplayName(ChatColor.translateAlternateColorCodes('&',voucher.name()));meta.setMaxStackSize(1);meta.setEnchantmentGlintOverride(true);meta.setLore(List.of("§7Type: §f"+voucher.kind(),"§7Grant: §f"+voucher.target(),"§7Duration: §f"+format(voucher.duration()),"§eRight-click to redeem. Timer starts on use.","§8One-use voucher. Copies share the same ID."));meta.getPersistentDataContainer().set(voucherId,PersistentDataType.STRING,voucher.id().toString());item.setItemMeta(meta);return item;}
 /** Trusted crate-plugin API. Every awarded copy gets its own persisted one-use ID. */
 public CompletableFuture<ItemStack> materializeReward(ItemStack template){
  CompletableFuture<ItemStack> result=new CompletableFuture<>();if(!Bukkit.isPrimaryThread()||!initialized||stopping){result.completeExceptionally(new IllegalStateException("Voucher service unavailable"));return result;}
  UUID id=token(template);if(id==null){result.complete(template.clone());return result;}
  io.execute(()->{try{GrantStore.Voucher fresh=store.copyVoucher(id);main(()->result.complete(item(fresh)));}catch(Exception e){result.completeExceptionally(e);}});return result;
 }
 private UUID token(ItemStack item){if(item==null||!item.hasItemMeta())return null;String value=item.getItemMeta().getPersistentDataContainer().get(voucherId,PersistentDataType.STRING);if(value==null)return null;try{return UUID.fromString(value);}catch(IllegalArgumentException e){return null;}}
 private static String format(long millis){long seconds=Math.max(0,(millis+999)/1000);long days=seconds/86400,hours=seconds%86400/3600,minutes=seconds%3600/60;return(days>0?days+"d ":"")+(hours>0?hours+"h ":"")+(minutes>0?minutes+"m ":"")+seconds%60+"s";}
 @Override public boolean onCommand(CommandSender sender,Command cmd,String label,String[] args){try{
  if(args.length==0){tell(sender,"/tempgrant list [player] | /tempgrant give <player> <rank|perm> <target> <timer> [amount] [custom name]");return true;}
  if(args[0].equalsIgnoreCase("list")){Player target;if(args.length==1&&sender instanceof Player p)target=p;else{if(!admin(sender)||args.length!=2)throw new IllegalArgumentException("/tempgrant list [online player]");target=Bukkit.getPlayerExact(args[1]);}if(target==null)throw new IllegalArgumentException("Player must be on this backend.");List<Grant> active=cached.getOrDefault(target.getUniqueId(),List.of()).stream().filter(g->g.expiry()>System.currentTimeMillis()).toList();tell(sender,target.getName()+": "+(active.isEmpty()?"no active temporary grants.":""));for(Grant g:active)tell(sender,g.kind()+" "+g.target()+" — "+format(g.expiry()-System.currentTimeMillis())+" remaining");return true;}
  if(!admin(sender))throw new IllegalArgumentException("You need ultimatetempgrants.admin.");if(!args[0].equalsIgnoreCase("give")||args.length<5)throw new IllegalArgumentException("/tempgrant give <online player> <rank|perm> <target> <timer> [1-36] [custom name]");Player target=Bukkit.getPlayerExact(args[1]);if(target==null||!ready(target))throw new IllegalArgumentException("Player must be ready on this backend.");String kind=Grant.kind(args[2]),grant=args[3];if(kind.equals("rank")){try{grant=(String)normalize.invoke(ranks,grant);}catch(Exception e){throw new IllegalArgumentException("Unknown rank. Examples: Ultimate+, Ultimate++, Ultimate+++, MOD");}}else {Grant.permission(grant);grant=grant.toLowerCase(Locale.ROOT);}long duration=Grant.duration(args[4]);int count=1,start=5;if(args.length>5&&args[5].matches("[0-9]+")){count=Integer.parseInt(args[5]);start=6;}if(count<1||count>36)throw new IllegalArgumentException("Amount must be 1-36; each item has a unique ID.");String name=args.length>start?String.join(" ",Arrays.copyOfRange(args,start,args.length)):getConfig().getString(kind.equals("rank")?"rank-item-name":"permission-item-name", "{target} Voucher").replace("{target}",grant).replace("{duration}",args[4]);if(name.isBlank()||name.length()>128)throw new IllegalArgumentException("Custom name must be 1-128 characters.");
  List<GrantStore.Voucher> vouchers=new ArrayList<>();for(int i=0;i<count;i++)vouchers.add(new GrantStore.Voucher(UUID.randomUUID(),kind,grant,duration,name));List<ItemStack> items=vouchers.stream().map(this::item).toList();if(plan(target,items)==null)throw new IllegalArgumentException("Player needs "+count+" empty inventory slot(s).");io.execute(()->{try{store.mint(vouchers);main(()->{ItemStack[] inventory=ready(target)?plan(target,items):null;if(inventory==null){tell(sender,"Delivery cancelled: player moved or inventory filled. No item was given; run the give command again.");return;}target.getInventory().setStorageContents(inventory);tell(sender,"Gave "+items.size()+" unique voucher item(s) to "+target.getName()+".");});}catch(Exception e){main(()->tell(sender,"Could not issue vouchers. No item was given."));}});return true;
 }catch(IllegalArgumentException e){tell(sender,e.getMessage());}return true;}
 private ItemStack[] plan(Player player,List<ItemStack> items){ItemStack[] original=player.getInventory().getStorageContents();ItemStack[] result=Arrays.stream(original).map(item->item==null?null:item.clone()).toArray(ItemStack[]::new);int index=0;for(int i=0;i<result.length&&index<items.size();i++)if(result[i]==null||result[i].getType().isAir())result[i]=items.get(index++).clone();return index==items.size()?result:null;}
 @EventHandler(priority=EventPriority.HIGHEST)public void use(PlayerInteractEvent e){if(e.getHand()==null||e.getAction()!=Action.RIGHT_CLICK_AIR&&e.getAction()!=Action.RIGHT_CLICK_BLOCK)return;Player p=e.getPlayer();ItemStack held=e.getHand()==EquipmentSlot.HAND?p.getInventory().getItemInMainHand():p.getInventory().getItemInOffHand();UUID id=token(held);if(id==null)return;e.setCancelled(true);if(!p.hasPermission("ultimatetempgrants.use")){tell(p,"You cannot redeem vouchers.");return;}if(!ready(p)){tell(p,"Network data is still loading. Try shortly.");return;}if(!pending.add(p.getUniqueId()))return;
  io.execute(()->{try{GrantStore.Redemption result=store.redeem(id,p.getUniqueId(),System.currentTimeMillis());List<Grant> values=store.active(p.getUniqueId(),System.currentTimeMillis());main(()->{pending.remove(p.getUniqueId());Player online=Bukkit.getPlayer(p.getUniqueId());if(online!=null){cached.put(p.getUniqueId(),values);if(result.applied()){if(ready(online))consume(online,id);pulse();tell(online,"Activated "+result.grant().kind()+" "+result.grant().target()+". Remaining: "+format(result.grant().expiry()-System.currentTimeMillis()));}else tell(online,"That voucher is invalid or has already been redeemed.");}});}catch(Exception ex){main(()->{pending.remove(p.getUniqueId());tell(p,"Could not confirm redemption. Keep the item and check /tempgrant list before retrying.");});}});
 }
 private void consume(Player p,UUID id){for(int slot=0;slot<p.getInventory().getSize();slot++){ItemStack item=p.getInventory().getItem(slot);if(id.equals(token(item))){if(item.getAmount()>1)item.setAmount(item.getAmount()-1);else item=null;p.getInventory().setItem(slot,item);return;}}}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true)public void place(BlockPlaceEvent e){if(token(e.getItemInHand())!=null)e.setCancelled(true);}
 @EventHandler public void join(PlayerJoinEvent e){refresh();}
 @EventHandler public void quit(PlayerQuitEvent e){UUID id=e.getPlayer().getUniqueId();PermissionAttachment a=permissions.remove(id);if(a!=null)e.getPlayer().removeAttachment(a);cached.remove(id);appliedRanks.remove(id);appliedPerms.remove(id);}
 @Override public List<String> onTabComplete(CommandSender s,Command c,String alias,String[] args){if(!admin(s))return args.length==1?List.of("list"):List.of();List<String> candidates= switch(args.length){case 1->List.of("give","list");case 2->Bukkit.getOnlinePlayers().stream().map(Player::getName).toList();case 3->List.of("rank","perm");case 4->args[2].equalsIgnoreCase("rank")?List.of("Ultimate+","Ultimate++","Ultimate+++","MEMBER","HELPER","TRIAL_MOD","MOD","ADMIN","DEV","OWNER"):List.of();case 5->List.of("30m","1h","1d","7d","30d");default->List.of();};String prefix=args[args.length-1].toLowerCase(Locale.ROOT);return candidates.stream().filter(v->v.toLowerCase(Locale.ROOT).startsWith(prefix)).toList();}
 @Override public void onDisable(){stopping=true;Bukkit.getScheduler().cancelTasks(this);for(Player p:Bukkit.getOnlinePlayers()){PermissionAttachment a=permissions.remove(p.getUniqueId());if(a!=null)p.removeAttachment(a);if(overlay!=null)try{overlay.invoke(ranks,p.getUniqueId(),Map.of());}catch(Exception ignored){}}io.shutdown();try{io.awaitTermination(6,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}io.shutdownNow();}
}
